let paging_mode = {
    // The arguments from the configuration file are prepended to the command-line
    // arguments. To make sure that -P / --no-paging and -pp take precedence over a
    // --paging option from the configuration file, we compare the positions of the
    // relevant arguments and let the last one win.
    let paging_index = if self.matches.occurrences_of("paging") > 0 {
        self.matches.index_of("paging")
    } else {
        None
    };
    let no_paging_index = self.matches.index_of("no-paging");
    let extra_plain_index = if self.matches.occurrences_of("plain") > 1 {
        self.matches
            .indices_of("plain")
            .and_then(|indices| indices.last())
    } else {
        None
    };

    let paging_disabled_index = match (no_paging_index, extra_plain_index) {
        (Some(no_paging), Some(plain)) => Some(std::cmp::max(no_paging, plain)),
        (Some(index), None) | (None, Some(index)) => Some(index),
        (None, None) => None,
    };

    let paging_disabled = match paging_disabled_index {
        Some(disabled_index) => {
            paging_index.map_or(true, |index| disabled_index > index)
        }
        None => false,
    };

    if paging_disabled {
        PagingMode::Never
    } else {
        match self.matches.value_of("paging") {
            Some("always") => PagingMode::Always,
            Some("never") => PagingMode::Never,
            Some("auto") | None => {
                if inputs.iter().any(Input::is_stdin) {
                    // If we are reading from stdin, only enable paging if we write to an
                    // interactive terminal and if we do not *read* from an interactive
                    // terminal.
                    if self.interactive_output && !atty::is(Stream::Stdin) {
                        PagingMode::QuitIfOneScreen
                    } else {
                        PagingMode::Never
                    }
                } else if self.interactive_output {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            }
            _ => unreachable!("other values for --paging are not allowed"),
        }
    }
};

